// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.documentimport com.roshan.persona.vision.barcode.RegionalQrFormatimport okhttp3.OkHttpClientimport okhttp3.Requestimport timber.log.Timberimport java.io.Fileimport java.io.FileOutputStreamimport java.security.MessageDigestimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — OkHttp Pack Downloader (Module 6 v4 — Step 6.5). * * Downloads Regional Vision Packs (RVP) over HTTPS via OkHttp. This is the * **fallback** path when Play Asset Delivery is unavailable (e.g., sideloaded * builds, devices without Play Store, or dev builds pointing at a test CDN). * * ## URL scheme * * Packs live at `${baseUrl}/${region}_pack.zip`, where `region` is the * lowercase enum name (e.g., `india_pack.zip`, `latam_pack.zip`). * * Pack metadata is delivered via HTTP response headers (so we don't need a * separate manifest fetch round-trip): * *  - `X-Pack-Version` — pack version string (e.g., `1.0.3`) *  - `X-Pack-Signature` — Ed25519 signature of the pack's SHA-256 hash *    (hex-encoded, 128 chars = 64 bytes) * * The SHA-256 hash + size are computed locally from the downloaded bytes — * never trusted from headers (defense in depth: an attacker controlling the * CDN could lie in headers but cannot forge a valid Ed25519 signature). * * ## Failure modes * *  - HTTP non-2xx → [DownloadResult] with `success=false` + errorMessage *  - Network exception → [DownloadResult] with `success=false` + errorMessage *  - Successful download but missing headers → signature will be empty; *    [Sha256PackVerifier.verify] will reject the pack (signature required). * * ## Privacy * *  - HTTPS-only (OkHttp is configured to reject cleartext by default). *  - No cookies, no auth headers — packs are public artifacts signed via *    Ed25519, so authenticity is verified post-download, not via transport. *  - Download URL contains only the region name — no user identifier. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Upgrade 5: Regional Vision Packs</a> */@Singletonclass OkHttpPackDownloader @Inject constructor(    private val httpClient: OkHttpClient,    /**     * Base URL of the pack CDN (no trailing slash). Defaults to the     * production CDN. Override via Hilt for development/test mirrors.     */    private val baseUrl: String = DEFAULT_BASE_URL,) : PackDownloader {    override suspend fun download(region: RegionalQrFormat, targetFile: File): DownloadResult {        val packFileName = "${region.name.lowercase()}_pack.zip"        val packUrl = "$baseUrl/$packFileName"        Timber.i("Downloading vision pack: %s → %s", packUrl, targetFile.absolutePath)        return try {            val request = Request.Builder().url(packUrl).get().build()            val response = httpClient.newCall(request).execute()            if (!response.isSuccessful) {                return DownloadResult(                    success = false,                    version = "",                    sizeBytes = 0L,                    sha256 = "",                    signature = "",                    errorMessage = "HTTP ${response.code}: ${response.message}",                )            }            val body = response.body ?: return DownloadResult(                success = false,                version = "",                sizeBytes = 0L,                sha256 = "",                signature = "",                errorMessage = "Empty response body",            )            targetFile.parentFile?.mkdirs()            val sha256 = body.byteStream().use { input ->                FileOutputStream(targetFile).use { output ->                    val digest = MessageDigest.getInstance("SHA-256")                    val buffer = ByteArray(BUFFER_SIZE)                    var read = input.read(buffer)                    while (read > 0) {                        digest.update(buffer, 0, read)                        output.write(buffer, 0, read)                        read = input.read(buffer)                    }                    digest.digest().joinToString("") { "%02x".format(it) }                }            }            val sizeBytes = targetFile.length()            val version = response.header(HEADER_PACK_VERSION) ?: DEFAULT_PACK_VERSION            val signature = response.header(HEADER_PACK_SIGNATURE).orEmpty()            Timber.i(                "Downloaded vision pack: %s → %s (%d bytes, sha256=%s, version=%s)",                packUrl, targetFile.absolutePath, sizeBytes, sha256, version,            )            DownloadResult(                success = true,                version = version,                sizeBytes = sizeBytes,                sha256 = sha256,                signature = signature,            )        } catch (e: Exception) {            Timber.e(e, "Vision pack download failed: %s", packUrl)            DownloadResult(                success = false,                version = "",                sizeBytes = 0L,                sha256 = "",                signature = "",                errorMessage = e.message ?: "Unknown download error",            )        }    }    private companion object {        private const val BUFFER_SIZE = 64 * 1024        /** Production CDN base URL for Regional Vision Packs. */        private const val DEFAULT_BASE_URL = "https://nous-cdn.roshan.dev/vision-packs/v1"        /** Default pack version if the CDN response omits the version header. */        private const val DEFAULT_PACK_VERSION = "1.0"        /** HTTP response header carrying the pack version string. */        private const val HEADER_PACK_VERSION = "X-Pack-Version"        /** HTTP response header carrying the Ed25519 signature (hex). */        private const val HEADER_PACK_SIGNATURE = "X-Pack-Signature"    }}
